import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { useAging } from './useAging';
import { useFigure } from '../locale/useLocale';

/** A person's due of their open claims that count, split by the claim's age on the sheet's today. */
function PersonAging({ sheetId, personId }: { sheetId: string; personId: number }) {
  const fig = useFigure();
  const aging = useAging(sheetId).get(personId);
  return (
    <>
      <td data-testid="person-aged-0-30">{fig(aging?.d0to30 ?? '')}</td>
      <td data-testid="person-aged-31-60">{fig(aging?.d31to60 ?? '')}</td>
      <td data-testid="person-aged-61">{fig(aging?.d61 ?? '')}</td>
    </>
  );
}

export const contributions = [
  PersonColumnHead.fill({ order: 23, Component: () => (
    <>
      <th>Aged 0–30</th>
      <th>Aged 31–60</th>
      <th>Aged 61+</th>
    </>
  ) }),
  PersonCells.fill({ order: 23, Component: PersonAging }),
];
import { counts, isOpen, useClaims } from '../claims/useClaims';
import { claimDueNow } from '../overdue/useOverdue';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { rateFor, sumDues, useRates } from '../rates/useRates';
import { useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';

export type Aging = { d0to30: string; d31to60: string; d61: string };

/** A claim's age on the sheet's today: the days from its date; 0 for a claim dated after today. */
export function ageDays(date: string, today: string): number {
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${date}T00:00:00Z`)) / 86_400_000;
  return Math.max(0, Math.round(days));
}

/** Each person's aging, by person id: the sum of the dues now of their OPEN and PENDING claims that count,
 *  split by the claim's age (0 to 30 days, 31 to 60, 61 or more), skipping those with none.
 *  Empty until the sheet's today is loaded. */
export function useAging(sheetId: string): Map<number, Aging> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId).data?.today;
  const holds = holdsById(people.data, today);
  const aging = new Map<number, Aging>();
  if (today === undefined) return aging;
  for (const p of people.data ?? []) {
    const buckets: [string[], string[], string[]] = [[], [], []];
    for (const c of claims.data ?? []) {
      if (c.personId !== p.id || !isOpen(c) || !counts(c, holds, today)) continue;
      const age = ageDays(c.date, today);
      const d = claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date, c.added), settings, today, gradeOn(p, c.date));
      buckets[age <= 30 ? 0 : age <= 60 ? 1 : 2].push(d);
    }
    aging.set(p.id, { d0to30: sumDues(buckets[0]), d31to60: sumDues(buckets[1]), d61: sumDues(buckets[2]) });
  }
  return aging;
}
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { sumDues } from '../rates/useRates';
import { useCutTotals } from './useCutTotals';
import { useFigure } from '../locale/useLocale';

/** A person's cut total: their cuts across every pool they are a member of, added up. */
function PersonCutTotal({ sheetId, personId }: { sheetId: string; personId: number }) {
  const fig = useFigure();
  const totals = useCutTotals(sheetId);
  return <td data-testid="person-cut-total">{fig(totals.get(personId) ?? '')}</td>;
}

/** The sheet's cut total: everyone's cut total added up. */
function CutTotal({ sheetId }: { sheetId: string }) {
  const fig = useFigure();
  const totals = useCutTotals(sheetId);
  return (
    <p>
      Cut total: <strong data-testid="rollup-cut-total">{fig(sumDues([...totals.values()]))}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHead.fill({ order: 24, Component: () => <th>Cut</th> }),
  PersonCells.fill({ order: 24, Component: PersonCutTotal }),
  SheetBody.fill({ order: 32, Component: ({ sheetId }) => <CutTotal sheetId={sheetId} /> }),
];
import { usePeople } from '../people/usePeople';
import { usePools } from '../pools/usePools';
import { money, hundredths } from '../rates/useRates';

/** Each person's cut total (two decimals), by person id: their cuts across every pool they are a member
 *  of, added up; a pool that shows no cut for them adds nothing. */
export function useCutTotals(sheetId: string): Map<number, string> {
  const people = usePeople(sheetId);
  const pools = usePools(sheetId);
  const totals = new Map<number, string>();
  if (people.data === undefined || pools.data === undefined) return totals;
  const cents = new Map<number, bigint>(people.data.map((p) => [p.id, 0n]));
  for (const pool of pools.data) {
    for (const m of pool.members) {
      if (m.personId === null || m.cut === null || !cents.has(m.personId)) continue;
      cents.set(m.personId, cents.get(m.personId)! + hundredths(m.cut));
    }
  }
  for (const [id, c] of cents) totals.set(id, money(c));
  return totals;
}
